.el-time-panel__content {
  font-size: 0;
  position: relative;
  overflow: hidden;
}

.el-time-panel__content::after,
.el-time-panel__content::before {
  content: "";
  top: 50%;
  position: absolute;
  margin-top: -15px;
  height: 32px;
  z-index: -1;
  left: 0;
  right: 0;
  box-sizing: border-box;
  padding-top: 6px;
  text-align: left;
