  left: 0;
  top: 0;
}

.el-rate__decimal {
  position: absolute;
  top: 0;
  left: 0;
  display: inline-block;
  overflow: hidden;
}

.el-rate__text {
  font-size: 14px;
  vertical-align: middle;
}

