}

.el-cascader-node__prefix {
  position: absolute;
  left: 10px;
}

.el-cascader-node__postfix {
  position: absolute;
  right: 10px;
}

.el-cascader-node__label {
  flex: 1;
  padding: 0 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.el-cascader-node > .el-radio {
  margin-right: 0;
}

.el-cascader-node > .el-radio .el-radio__label {
  padding-left: 0;
}

