  overflow: hidden;
}

.el-drawer.rtl {
  animation: rtl-drawer-out 0.3s;
}

.el-drawer__open .el-drawer.rtl {
  animation: rtl-drawer-in 0.3s 1ms;
}

.el-drawer.ltr {
